#include <algorithm>
#include <climits>
#include <queue>
#include <string>
#include <vector>

struct Cell { int x, y; };
struct Enemy { Cell pos; int hp; };

class Dungeon
{
public:
    explicit Dungeon(const std::vector<std::string>& rows) : m_map{ rows }
    {
        for (int y{ 0 }; y < static_cast<int>(m_map.size()); ++y)
            for (int x{ 0 }; x < static_cast<int>(m_map[static_cast<std::size_t>(y)].size()); ++x)
            {
                char& c{ m_map[static_cast<std::size_t>(y)][static_cast<std::size_t>(x)] };
                if (c == 'P') { m_player = { x, y }; c = '.'; }
                else if (c == 'E') { m_enemies.push_back({ { x, y }, 2 }); c = '.'; }
                else if (c == 'C') { m_coins.push_back({ x, y }); c = '.'; }
                else if (c == 'X') { m_exit = { x, y }; c = '.'; }
            }
    }

    bool move(int dx, int dy)
    {
        if (over()) return false;
        const Cell to{ m_player.x + dx, m_player.y + dy };
        if (!walkable(to)) return false;
        if (const int e{ enemyAt(to) }; e >= 0)
        {
            if (--m_enemies[static_cast<std::size_t>(e)].hp <= 0) m_enemies.erase(m_enemies.begin() + e);
        }
        else
        {
            m_player = to;
            for (std::size_t i{ 0 }; i < m_coins.size(); ++i)
                if (same(m_coins[i], to)) { m_coins.erase(m_coins.begin() + static_cast<std::ptrdiff_t>(i)); ++m_collected; break; }
            if (same(m_player, m_exit) && m_coins.empty()) { m_won = true; return true; }
        }
        enemiesAct();
        return true;
    }

    bool wait()
    {
        if (over()) return false;
        enemiesAct();
        return true;
    }

    std::vector<Cell> travelPath(Cell to) const
    {
        if (!walkable(to)) return {};
        const int w{ width() }, h{ static_cast<int>(m_map.size()) };
        std::vector<int> cost(static_cast<std::size_t>(w * h), INT_MAX), came(static_cast<std::size_t>(w * h), -1);
        using Item = std::pair<int, int>;
        std::priority_queue<Item, std::vector<Item>, std::greater<Item>> open;
        const int start{ m_player.y * w + m_player.x };
        cost[static_cast<std::size_t>(start)] = 0;
        open.push({ 0, start });
        while (!open.empty())
        {
            const auto [c, i] { open.top() };
            open.pop();
            if (c > cost[static_cast<std::size_t>(i)]) continue;
            const Cell cur{ i % w, i / w };
            if (same(cur, to)) break;
            for (int d{ 0 }; d < 4; ++d)
            {
                const Cell n{ cur.x + DX[d], cur.y + DY[d] };
                if (!walkable(n)) continue;
                const int ni{ n.y * w + n.x };
                const int nc{ c + (tile(n) == '~' ? 3 : 1) };
                if (nc < cost[static_cast<std::size_t>(ni)]) { cost[static_cast<std::size_t>(ni)] = nc; came[static_cast<std::size_t>(ni)] = i; open.push({ nc, ni }); }
            }
        }
        const int goal{ to.y * w + to.x };
        if (cost[static_cast<std::size_t>(goal)] == INT_MAX) return {};
        std::vector<Cell> path;
        for (int i{ goal }; i != -1; i = came[static_cast<std::size_t>(i)]) path.push_back({ i % w, i / w });
        std::reverse(path.begin(), path.end());
        return path;
    }

    Cell player() const { return m_player; }
    int hp() const { return m_hp; }
    int coins() const { return m_collected; }
    int coinsLeft() const { return static_cast<int>(m_coins.size()); }
    const std::vector<Enemy>& enemies() const { return m_enemies; }
    bool won() const { return m_won; }
    bool lost() const { return m_hp <= 0; }

private:
    static constexpr int DX[4]{ 0, 1, 0, -1 };
    static constexpr int DY[4]{ -1, 0, 1, 0 };

    static bool same(Cell a, Cell b) { return a.x == b.x && a.y == b.y; }
    bool over() const { return m_won || lost(); }
    int width() const { int w{ 0 }; for (const auto& r : m_map) w = std::max(w, static_cast<int>(r.size())); return w; }

    char tile(Cell c) const
    {
        if (c.y < 0 || c.y >= static_cast<int>(m_map.size()) || c.x < 0 || c.x >= static_cast<int>(m_map[static_cast<std::size_t>(c.y)].size())) return '#';
        return m_map[static_cast<std::size_t>(c.y)][static_cast<std::size_t>(c.x)];
    }
    bool walkable(Cell c) const { return tile(c) != '#'; }

    int enemyAt(Cell c) const
    {
        for (std::size_t i{ 0 }; i < m_enemies.size(); ++i) if (same(m_enemies[i].pos, c)) return static_cast<int>(i);
        return -1;
    }

    std::vector<int> distances() const
    {
        const int w{ width() }, h{ static_cast<int>(m_map.size()) };
        std::vector<int> dist(static_cast<std::size_t>(w * h), -1);
        std::queue<Cell> q;
        q.push(m_player);
        dist[static_cast<std::size_t>(m_player.y * w + m_player.x)] = 0;
        while (!q.empty())
        {
            const Cell c{ q.front() };
            q.pop();
            for (int d{ 0 }; d < 4; ++d)
            {
                const Cell n{ c.x + DX[d], c.y + DY[d] };
                if (!walkable(n) || dist[static_cast<std::size_t>(n.y * w + n.x)] != -1) continue;
                dist[static_cast<std::size_t>(n.y * w + n.x)] = dist[static_cast<std::size_t>(c.y * w + c.x)] + 1;
                q.push(n);
            }
        }
        return dist;
    }

    void enemiesAct()
    {
        const int w{ width() };
        const std::vector<int> dist{ distances() };
        auto at = [&](Cell c) { return walkable(c) ? dist[static_cast<std::size_t>(c.y * w + c.x)] : -1; };
        for (Enemy& e : m_enemies)
        {
            if (std::abs(e.pos.x - m_player.x) + std::abs(e.pos.y - m_player.y) == 1)
            {
                if (--m_hp <= 0) return;
                continue;
            }
            const int mine{ at(e.pos) };
            if (mine < 0 || mine > 8) continue;
            Cell best{ e.pos };
            int bestDist{ mine };
            for (int d{ 0 }; d < 4; ++d)
            {
                const Cell n{ e.pos.x + DX[d], e.pos.y + DY[d] };
                const int v{ at(n) };
                if (v < 0 || v >= bestDist || enemyAt(n) >= 0 || same(n, m_player)) continue;
                best = n;
                bestDist = v;
            }
            e.pos = best;
        }
    }

    std::vector<std::string> m_map;
    Cell m_player{ 0, 0 }, m_exit{ -1, -1 };
    std::vector<Enemy> m_enemies;
    std::vector<Cell> m_coins;
    int m_hp{ 3 }, m_collected{ 0 };
    bool m_won{ false };
};

unitTests:
const std::vector<std::string> keep{
    "#########",
    "#P..~..X#",
    "#.##.##.#",
    "#C.....E#",
    "#########",
};
bool at(Cell c, int x, int y) { return c.x == x && c.y == y; }
TEST("loading") { const Dungeon d{ keep }; CHECK(at(d.player(), 1, 1)); CHECK_EQ(d.coinsLeft(), 1); CHECK_EQ(d.enemies().size(), std::size_t{ 1 }); CHECK(at(d.enemies()[0].pos, 7, 3)); CHECK_EQ(d.hp(), 3); }
TEST("walls take no turn") { Dungeon d{ keep }; CHECK(!d.move(0, -1)); CHECK(at(d.player(), 1, 1)); CHECK(at(d.enemies()[0].pos, 7, 3)); }
TEST("the enemy chases") {
    Dungeon d{ keep };
    CHECK(d.move(1, 0)); CHECK(at(d.player(), 2, 1)); CHECK(at(d.enemies()[0].pos, 7, 2));
    d.move(1, 0); CHECK(at(d.enemies()[0].pos, 7, 1)); d.move(1, 0); CHECK(at(d.enemies()[0].pos, 6, 1));
}
TEST("fighting") {
    Dungeon d{ keep }; for (int i = 0; i < 4; ++i) d.move(1, 0);
    CHECK(at(d.player(), 5, 1)); CHECK_EQ(d.hp(), 2);
    d.move(1, 0); CHECK(at(d.player(), 5, 1)); CHECK_EQ(d.enemies()[0].hp, 1); CHECK_EQ(d.hp(), 1);
    d.move(1, 0); CHECK(d.enemies().empty()); CHECK_EQ(d.hp(), 1); CHECK(!d.lost());
}
TEST("coins, then the exit") {
    Dungeon d{ keep }; for (int i = 0; i < 6; ++i) d.move(1, 0);
    d.move(1, 0); d.move(1, 0); CHECK(at(d.player(), 7, 1)); CHECK(!d.won());
    d.move(0, 1); d.move(0, 1); for (int i = 0; i < 6; ++i) d.move(-1, 0);
    CHECK(at(d.player(), 1, 3)); CHECK_EQ(d.coins(), 1); CHECK_EQ(d.coinsLeft(), 0);
    for (int i = 0; i < 6; ++i) d.move(1, 0); d.move(0, -1); d.move(0, -1);
    CHECK(d.won()); CHECK(!d.move(-1, 0)); CHECK(!d.wait());
}
TEST("losing") {
    Dungeon d{ { "#####", "#P.E#", "#####" } };
    d.wait(); CHECK(at(d.enemies()[0].pos, 2, 1)); CHECK_EQ(d.hp(), 3);
    d.wait(); d.wait(); CHECK_EQ(d.hp(), 1); d.wait(); CHECK(d.lost()); CHECK(!d.move(1, 0));
}
TEST("enemies do not stack") {
    Dungeon d{ { "#######", "#P..EE#", "#######" } };
    d.wait(); CHECK(at(d.enemies()[0].pos, 3, 1)); CHECK(at(d.enemies()[1].pos, 4, 1));
    d.wait(); CHECK(at(d.enemies()[0].pos, 2, 1)); CHECK(at(d.enemies()[1].pos, 3, 1));
    d.wait(); CHECK_EQ(d.hp(), 2); CHECK(at(d.enemies()[1].pos, 3, 1));
}
TEST("too far to notice") { Dungeon d{ { "#############", "#P.........E#", "#############" } }; d.wait(); CHECK(at(d.enemies()[0].pos, 11, 1)); }
TEST("travelling around the swamp") {
    const Dungeon d{ { "#######", "#P~~~.#", "#.###.#", "#.....#", "#######" } };
    const auto path = d.travelPath({ 5, 1 });
    CHECK_EQ(path.size(), std::size_t{ 9 }); CHECK(at(path.front(), 1, 1)); CHECK(at(path.back(), 5, 1));
    bool steps = true; for (std::size_t i = 1; i < path.size(); ++i) steps = steps && std::abs(path[i].x - path[i - 1].x) + std::abs(path[i].y - path[i - 1].y) == 1;
    CHECK(steps); CHECK(d.travelPath({ 0, 0 }).empty());
    const Dungeon shut{ { "#####", "#P#.#", "#####" } }; CHECK(shut.travelPath({ 3, 1 }).empty());
}

